  <header>
    <h1>Settings</h1>
    <button id="to-home" class="icon-btn" title="Back" aria-label="Back">✕</button>
  </header>
  <dl id="settings-info"></dl>
  <button id="verify">Verify round-trip</button>
  <ol class="steps" id="steps"></ol>
  <button id="forget" class="danger">Forget settings on this device</button>
