########## app.js
import { APPS } from './shared/apps.js';
import { getConfig, setConfig, persist, queuedCount } from './shared/store.js';
import { testConnection, bootstrap, pull, write, drain } from './shared/github.js';
import { serialize } from './shared/md.js';

const $ = s => document.querySelector(s);
const show = id => document.querySelectorAll('section').forEach(s => s.hidden = s.id !== id);
const status = (text, bad) => {
  const el = $('#status');
  el.textContent = text;
  el.classList.toggle('bad', !!bad);
};

// ---- setup ----

$('#setup-form').addEventListener('submit', async e => {
  e.preventDefault();
  const btn = e.target.querySelector('button');
  const msg = $('#setup-msg');
  const cfg = Object.fromEntries(new FormData(e.target));
  btn.disabled = true;
  msg.className = 'msg';
  msg.textContent = 'Checking…';
  try {
    const info = await testConnection(cfg);
    await setConfig(cfg);
    await persist();
    msg.textContent = info.private ? '' : 'Note: that repo is public.';
    await home();
  } catch (err) {
    msg.textContent = err.message;
    msg.className = 'msg bad';
  } finally {
    btn.disabled = false;
  }
});

// ---- home ----

async function home() {
  const cfg = await getConfig();

  $('#tiles').replaceChildren(...APPS.map(a => {
    const link = document.createElement('a');
    link.className = 'tile';
    link.href = `./${a.slug}/`;
    const img = document.createElement('img');
    img.src = `./${a.slug}/icon.svg`;
    img.alt = '';
    const name = document.createElement('span');
    name.textContent = a.label;
    link.append(img, name);
    return link;
  }));

  const days = cfg.expiresAt ? Math.ceil((new Date(cfg.expiresAt) - Date.now()) / 86400000) : null;
  const expiry = $('#expiry');
  expiry.hidden = days === null || days > 14;
  if (!expiry.hidden) {
    expiry.textContent = days <= 0
      ? 'Your token has expired. Replace it in settings.'
      : `Your token expires in ${days} day(s). Replace it in settings.`;
  }

  show('home');
  await refresh();
}

async function refresh() {
  const pending = await queuedCount();
  if (pending) return status(`${pending} change(s) pending`);
  status('checking…');
  try {
    const r = await pull();
    status(r.empty ? 'repo is empty'
      : r.unchanged ? 'in sync'
      : `in sync — ${r.changed} file(s) updated`);
  } catch (err) {
    status(err.message, true);
  }
}

addEventListener('focus', () => { if (!$('#home').hidden) refresh(); });

// ---- settings ----

$('#to-settings').addEventListener('click', async () => {
  const cfg = await getConfig();
  $('#settings-info').replaceChildren(...Object.entries({
    Repo: `${cfg.owner}/${cfg.repo}`,
    Branch: cfg.branch,
    Token: `on this device only${cfg.expiresAt ? `, expires ${cfg.expiresAt}` : ''}`
  }).flatMap(([k, v]) => {
    const dt = document.createElement('dt');
    const dd = document.createElement('dd');
    dt.textContent = k;
    dd.textContent = v;
    return [dt, dd];
  }));
  $('#steps').replaceChildren();
  show('settings');
});

$('#to-home').addEventListener('click', home);

$('#forget').addEventListener('click', () => {
  if (!confirm('Remove the repo settings and token from this device? Your data in GitHub is untouched.')) return;
  indexedDB.deleteDatabase('mine');
  location.reload();
});

// Proves the architecture against the real repo: GraphQL read, atomic write, pull back.
$('#verify').addEventListener('click', async () => {
  const list = $('#steps');
  list.replaceChildren();
  const add = text => {
    const li = document.createElement('li');
    li.textContent = text;
    list.append(li);
    return li;
  };
  const run = async (text, fn) => {
    const li = add(`${text} …`);
    try {
      li.textContent = `${text} — ${await fn()}`;
      li.className = 'done';
    } catch (err) {
      li.textContent = `${text} — failed: ${err.message}`;
      li.className = 'bad';
      throw err;
    }
  };

  try {
    await run('Read repo', async () => {
      const i = await testConnection(await getConfig());
      return `${i.name}, ${i.private ? 'private' : 'PUBLIC'}`;
    });
    await run('Bootstrap over GraphQL', async () => {
      const b = await bootstrap('');
      return b.empty ? 'repo is empty, nothing to mirror yet' : `${b.files.length} markdown file(s)`;
    });
    await run('Write README.md, one commit', async () => {
      await write('README.md', serialize(
        { title: 'Mine data', verified: new Date().toISOString() },
        'Markdown written by Mine. Safe to edit by hand.'));
      return `commit ${(await drain('Verify round-trip from Mine')).commit.slice(0, 7)}`;
    });
    await run('Pull it back', async () => `${(await pull()).changed} file(s) reconciled`);
    add('Round-trip complete').className = 'done';
  } catch {
    /* the failing step already says why */
  }
});

// ---- service worker ----

function registerSW() {
  if (!navigator.serviceWorker) return;
  navigator.serviceWorker.register('./sw.js', { type: 'module', scope: './' }).then(reg => {
    const offer = () => { $('#update').hidden = false; };
    if (reg.waiting && navigator.serviceWorker.controller) offer();
    reg.addEventListener('updatefound', () => {
      const w = reg.installing;
      w?.addEventListener('statechange', () => {
        if (w.state === 'installed' && navigator.serviceWorker.controller) offer();
      });
    });
    $('#reload').addEventListener('click', () => {
      reg.waiting?.postMessage('skip-waiting');
      navigator.serviceWorker.addEventListener('controllerchange',
        () => location.reload(), { once: true });
    });
  }).catch(() => { /* an app that cannot cache still works online */ });
}

// ---- boot ----

registerSW();
if (await getConfig()) await home(); else show('setup');
########## style.css
:root {
  --bg: #fff; --fg: #1f2933; --muted: #6b7280; --line: #e4e7eb;
  --accent: #1f2933; --bad: #c0392b; --good: #0a7b3e; --soft: #f5f7fa;
}
@media (prefers-color-scheme: dark) {
  :root { --bg: #15191e; --fg: #e8eaed; --muted: #9aa5b1; --line: #2b3138;
          --accent: #e8eaed; --bad: #ff8a7a; --good: #5bd48b; --soft: #1d2229; }
}
* { box-sizing: border-box; }
body {
  margin: 0; padding: 16px max(16px, env(safe-area-inset-left)) 24px;
  max-width: 44rem; margin-inline: auto;
  font: 16px/1.5 system-ui, -apple-system, sans-serif;
  color: var(--fg); background: var(--bg);
}
header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
h1 { font-size: 1.4rem; margin: .2rem 0 .6rem; }
.lede { color: var(--muted); margin-top: 0; }

label { display: block; margin: .9rem 0; font-size: .85rem; color: var(--muted); }
input {
  display: block; width: 100%; margin-top: .3rem; padding: .75rem;
  font: inherit; color: var(--fg); background: var(--bg);
  border: 1px solid var(--line); border-radius: .5rem;
}
button {
  width: 100%; padding: .9rem; margin: .4rem 0; font: inherit; font-weight: 600;
  color: var(--bg); background: var(--accent);
  border: 0; border-radius: .6rem; cursor: pointer;
}
button[disabled] { opacity: .5; }
button.danger { color: var(--bad); background: none; border: 1px solid var(--line); }
.icon-btn {
  width: auto; padding: .4rem .7rem; font-size: 1.1rem; line-height: 1;
  color: var(--fg); background: none; border: 1px solid var(--line);
  border-radius: .5rem; text-decoration: none;
}

.tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(7rem, 1fr)); gap: .8rem; margin: 1rem 0; }
.tile {
  display: flex; flex-direction: column; align-items: center; gap: .5rem;
  padding: 1.2rem .5rem; text-decoration: none; color: var(--fg);
  background: var(--soft); border-radius: .8rem;
}
.tile img { width: 2.2rem; height: 2.2rem; }
.tile span { font-size: .85rem; }

dl { display: grid; grid-template-columns: auto 1fr; gap: .4rem 1rem; margin: 1rem 0; font-size: .9rem; }
dt { color: var(--muted); }
dd { margin: 0; word-break: break-word; }

.status, .msg { font-size: .85rem; color: var(--muted); }
.bad { color: var(--bad); }
.banner {
  padding: .7rem .9rem; margin: .6rem 0; font-size: .85rem;
  background: var(--soft); border-left: 3px solid var(--bad); border-radius: .3rem;
}
.banner.update {
  position: fixed; inset: auto 1rem 1rem; display: flex; align-items: center;
  justify-content: space-between; gap: 1rem; border-left-color: var(--good);
  box-shadow: 0 2px 12px rgb(0 0 0 / .18);
}
.banner.update button { width: auto; padding: .45rem .9rem; }

.steps { padding-left: 1.2rem; font-size: .85rem; color: var(--muted); }
.steps li { margin: .35rem 0; }
.steps li.done { color: var(--good); }
.steps li.bad { color: var(--bad); }

