cat > calendar/style.css <<'CSS'
/* Calendar. Phone first: the desktop grid is the enhancement, not the other way round.
   A month cell is ~50px wide on a phone, so entry rows are neither readable nor tappable -
   there the cells carry group-coloured dots and a tap opens a sheet. */

:root { --cell: 3.1rem; --today: #1f66d0; }
@media (prefers-color-scheme: dark) { :root { --today: #6ea8ff; } }

body { max-width: none; padding: 0; padding-bottom: env(safe-area-inset-bottom); }
#cal { display: flex; flex-direction: column; min-height: 100vh; min-height: 100dvh; }

/* ---- top pane ---- */
.topbar {
  position: sticky; top: 0; z-index: 5;
  display: flex; align-items: center; gap: .35rem;
  padding: max(.5rem, env(safe-area-inset-top)) .6rem .5rem;
  background: var(--bg); border-bottom: 1px solid var(--line);
}
.topbar .spacer { flex: 1; }
.nav {
  width: auto; min-width: 2.4rem; min-height: 2.4rem; margin: 0; padding: .3rem .55rem;
  font-size: 1.1rem; line-height: 1; font-weight: 500;
  color: var(--fg); background: var(--soft); border: 0; border-radius: .5rem;
}
.nav.wide { font-size: .85rem; padding: .5rem .7rem; }
.period {
  width: auto; margin: 0; padding: .45rem .6rem; font-size: 1rem; font-weight: 600;
  color: var(--fg); background: none; border: 0; white-space: nowrap;
}
.caret { margin-left: .3rem; font-size: .7rem; opacity: .6; }
#groups-btn, #today { display: none; }
#menu-btn { display: inline-block; }

/* ---- week header + grid ---- */
.weekhead {
  display: grid; grid-template-columns: repeat(7, 1fr);
  padding: .35rem .25rem 0; font-size: .7rem; font-weight: 600;
  color: var(--muted); text-align: center; text-transform: uppercase; letter-spacing: .04em;
}
.weekhead span.we { color: var(--today); }

.grid {
  display: grid; grid-template-columns: repeat(7, 1fr);
  gap: 1px; padding: .25rem; flex: 1;
}
.day {
  display: flex; flex-direction: column; align-items: stretch; gap: .15rem;
  min-height: var(--cell); padding: .2rem .15rem;
  text-align: left; font: inherit; color: var(--fg);
  background: var(--bg); border: 0; border-radius: .35rem; cursor: pointer;
}
.day.we { background: var(--soft); }
.day.out { opacity: .38; }
.num {
  align-self: center; min-width: 1.6rem; padding: .12rem 0;
  font-size: .8rem; font-variant-numeric: tabular-nums; text-align: center;
  color: var(--muted); border-radius: 999px;
}
.day.today .num { color: #fff; background: var(--today); font-weight: 700; }

/* phone: dots */
.dots { display: flex; flex-wrap: wrap; justify-content: center; align-content: flex-start; gap: 3px; }
.dot { width: 7px; height: 7px; border-radius: 999px; background: var(--c); }
.dot.open { box-shadow: inset 0 0 0 7px var(--c); }
.dot.done { background: none; box-shadow: inset 0 0 0 1.5px var(--c); }
.more { font-size: .6rem; color: var(--muted); line-height: 7px; }

