  background: var(--soft); border-radius: .25rem; cursor: pointer;
}
.erow .bar { flex: none; width: 3px; align-self: stretch; min-height: .9rem; border-radius: 2px; background: var(--c); }
.erow .when { flex: none; color: var(--muted); font-variant-numeric: tabular-nums; }
.erow .what { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.erow.done .what { text-decoration: line-through; color: var(--muted); }
.tick {
  flex: none; width: 1rem; height: .8rem; margin: 0; padding: 0;
  background: none; border: 1.5px solid var(--muted); border-radius: 2px; cursor: pointer;
}
.erow.done .tick { background: var(--c); border-color: var(--c); }

.sync { padding: .4rem .7rem; margin: 0; font-size: .75rem; }

/* ---- popovers, sheets, modal ---- */
.scrim { position: fixed; inset: 0; z-index: 8; background: rgb(0 0 0 / .35); }
.pop {
  position: fixed; z-index: 10; width: min(19rem, calc(100vw - 1.5rem));
