.sheet {
  position: fixed; inset: auto 0 0; z-index: 10; max-height: 82dvh; overflow-y: auto;
  padding: .3rem 1rem calc(1rem + env(safe-area-inset-bottom));
  background: var(--bg); border-radius: 1rem 1rem 0 0; box-shadow: 0 -4px 30px rgb(0 0 0 / .3);
}
.sheet-grip { width: 2.4rem; height: 4px; margin: .5rem auto .6rem; background: var(--line); border-radius: 2px; }
.sheet h2 { margin: .2rem 0 .7rem; font-size: 1.05rem; }
.btn-link { display: block; width: 100%; padding: .9rem; margin: .4rem 0; font-weight: 600;
  color: var(--fg); background: var(--soft); border-radius: .6rem; text-align: center; text-decoration: none; }
button.ghost { color: var(--fg); background: none; border: 1px solid var(--line); }

.day-list { display: flex; flex-direction: column; gap: .4rem; margin-bottom: .8rem; }
.day-empty { font-size: .85rem; color: var(--muted); }
.dentry {
  display: flex; align-items: center; gap: .6rem; width: 100%; margin: 0;
  padding: .7rem .6rem; font: inherit; text-align: left;
  color: var(--fg); background: var(--soft); border: 0; border-radius: .55rem; cursor: pointer;
}
.dentry .bar { flex: none; width: 4px; align-self: stretch; border-radius: 2px; background: var(--c); }
.dentry .mid { flex: 1; min-width: 0; }
.dentry .dt { display: block; font-size: .72rem; color: var(--muted); }
.dentry .dn { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dentry.done .dn { text-decoration: line-through; color: var(--muted); }
.dentry .tick { width: 1.5rem; height: 1.2rem; }
.rep { font-size: .62rem; color: var(--muted); }

/* ---- entry popup ---- */
.modal {
  position: fixed; inset: 0; z-index: 12; display: flex; align-items: flex-end; justify-content: center;
  background: rgb(0 0 0 / .4); overflow-y: auto; overscroll-behavior: contain;
}
.card {
  width: min(32rem, 100%); max-height: 94dvh; overflow-y: auto;
  padding: 1rem 1rem calc(1rem + env(safe-area-inset-bottom));
  background: var(--bg); border-radius: 1rem 1rem 0 0;
}
.title-in { font-size: 1.1rem; font-weight: 600; padding: .7rem .6rem; }
.card label { margin: .7rem 0 0; }
