.pop {
  position: fixed; z-index: 10; width: min(19rem, calc(100vw - 1.5rem));
  padding: .7rem; background: var(--bg);
  border: 1px solid var(--line); border-radius: .7rem; box-shadow: 0 8px 30px rgb(0 0 0 / .25);
}
.pop-head { display: flex; align-items: center; gap: .3rem; margin-bottom: .5rem; }
.pop-head .spacer { flex: 1; }
.pop-title { width: auto; margin: 0; padding: .3rem .4rem; font-weight: 600; color: var(--fg); background: none; border: 0; }
.link { width: auto; margin: 0; padding: .2rem .4rem; font-size: .78rem; font-weight: 500; color: var(--today); background: none; border: 0; }

.pick-body { display: grid; gap: 2px; }
.pick-body.days { grid-template-columns: repeat(7, 1fr); }
.pick-body.years { grid-template-columns: repeat(3, 1fr); }
.pick-body .wh { font-size: .62rem; color: var(--muted); text-align: center; text-transform: uppercase; }
.pk {
  width: auto; margin: 0; padding: .45rem .1rem; font-size: .8rem; font-weight: 500;
  color: var(--fg); background: none; border: 0; border-radius: .35rem;
}
.pk.out { color: var(--muted); opacity: .55; }
.pk.now { color: #fff; background: var(--today); font-weight: 700; }
.pick-body.years .pk { padding: .7rem .1rem; }

.groups-list { display: flex; flex-direction: column; gap: .1rem; }
.glab { display: flex; align-items: center; gap: .55rem; padding: .5rem .3rem; font-size: .9rem; color: var(--fg); cursor: pointer; }
.glab input { width: 1.1rem; height: 1.1rem; margin: 0; flex: none; }
.swatch { flex: none; width: .85rem; height: .85rem; border-radius: 999px; background: var(--c); }

.sheet {
  position: fixed; inset: auto 0 0; z-index: 10; max-height: 82dvh; overflow-y: auto;
  padding: .3rem 1rem calc(1rem + env(safe-area-inset-bottom));
  background: var(--bg); border-radius: 1rem 1rem 0 0; box-shadow: 0 -4px 30px rgb(0 0 0 / .3);
}
.sheet-grip { width: 2.4rem; height: 4px; margin: .5rem auto .6rem; background: var(--line); border-radius: 2px; }
.sheet h2 { margin: .2rem 0 .7rem; font-size: 1.05rem; }
.btn-link { display: block; width: 100%; padding: .9rem; margin: .4rem 0; font-weight: 600;
  color: var(--fg); background: var(--soft); border-radius: .6rem; text-align: center; text-decoration: none; }
button.ghost { color: var(--fg); background: none; border: 1px solid var(--line); }

.day-list { display: flex; flex-direction: column; gap: .4rem; margin-bottom: .8rem; }
.day-empty { font-size: .85rem; color: var(--muted); }
.dentry {
  display: flex; align-items: center; gap: .6rem; width: 100%; margin: 0;
  padding: .7rem .6rem; font: inherit; text-align: left;
  color: var(--fg); background: var(--soft); border: 0; border-radius: .55rem; cursor: pointer;
}
.dentry .bar { flex: none; width: 4px; align-self: stretch; border-radius: 2px; background: var(--c); }
.dentry .mid { flex: 1; min-width: 0; }
.dentry .dt { display: block; font-size: .72rem; color: var(--muted); }
.dentry .dn { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dentry.done .dn { text-decoration: line-through; color: var(--muted); }
.dentry .tick { width: 1.5rem; height: 1.2rem; }
.rep { font-size: .62rem; color: var(--muted); }

/* ---- entry popup ---- */
.modal {
  position: fixed; inset: 0; z-index: 12; display: flex; align-items: flex-end; justify-content: center;
  background: rgb(0 0 0 / .4); overflow-y: auto; overscroll-behavior: contain;
}
.card {
  width: min(32rem, 100%); max-height: 94dvh; overflow-y: auto;
  padding: 1rem 1rem calc(1rem + env(safe-area-inset-bottom));
  background: var(--bg); border-radius: 1rem 1rem 0 0;
}
.title-in { font-size: 1.1rem; font-weight: 600; padding: .7rem .6rem; }
.card label { margin: .7rem 0 0; }
.card small { display: block; margin-top: .25rem; font-size: .7rem; color: var(--muted); }
.row2 { display: flex; gap: .6rem; }
.row2 label { flex: 1; }
.row2 label.t { flex: 0 0 8rem; }
.check { display: flex; align-items: center; gap: .5rem; margin: .7rem 0 0; font-size: .9rem; color: var(--fg); }
.check input { width: 1.1rem; height: 1.1rem; margin: 0; }
select {
  display: block; width: 100%; margin-top: .3rem; padding: .75rem; font: inherit;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: .5rem;
}
.btngroup { display: flex; gap: 0; margin: .8rem 0 0; }
.seg {
  flex: 1; width: auto; margin: 0; padding: .6rem .4rem; font-size: .85rem; font-weight: 500;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: 0;
}
.seg:first-child { border-radius: .5rem 0 0 .5rem; }
.seg:last-child { border-radius: 0 .5rem .5rem 0; border-left: 0; }
.seg[aria-pressed="true"] { color: var(--bg); background: var(--accent); border-color: var(--accent); }
.scope { margin-top: .8rem; }
.scope-note { font-size: .75rem; color: var(--muted); }
.body-in {
  display: block; width: 100%; margin-top: .3rem; padding: .7rem;
  font: .85rem/1.5 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: .5rem;
  resize: none; overflow: hidden;
}
.actions { display: flex; flex-wrap: wrap; gap: .5rem; margin-top: 1.1rem; }
.actions button { flex: 1; min-width: 6rem; margin: 0; }
.path { margin: .6rem 0 0; font-size: .65rem; color: var(--muted); word-break: break-all; }
.hidden { display: none !important; }

/* ---- desktop ---- */
@media (min-width: 600px) {
  :root { --cell: 6.6rem; }
  #cal { max-width: 70rem; margin-inline: auto; }
  .topbar { padding: .7rem .8rem; }
  #groups-btn, #today { display: inline-flex; align-items: center; }
  #menu-btn { display: none; }
  .period { font-size: 1.15rem; }
  .weekhead { font-size: .75rem; padding: .5rem .3rem .2rem; }
  .day { padding: .25rem; }
  .num { align-self: flex-end; margin-right: .1rem; }
  .dots { display: none; }
  .rows { display: flex; }
  .modal { align-items: center; }
  .card { border-radius: .9rem; max-height: 88dvh; }
  .sheet { display: none !important; }
}
CSS
echo "written $(wc -l < calendar/style.css) lines"

