// Seeds maximilianharr/mine-data through the calendar's own pure write path (entryFile +
// pathFor), then reads every file back through buildModel/occurrences and checks that the
// round trip is exact. Node side only: the browser runs the same functions.
import { readFileSync } from 'node:fs';
import { entryFile, pathFor, buildModel, occurrences, timeLabel } from '/home/max/ws/mine/calendar/data.js';

const env = Object.fromEntries(readFileSync('/home/max/ws/mine/.env.secrets', 'utf8')
  .split('\n').filter(l => l.includes('=')).map(l => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1).trim()]));
const { GITHUB_OWNER: O, GITHUB_REPO: R, GITHUB_BRANCH: B, GITHUB_TOKEN: T } = env;
const api = async (p, init = {}) => {
  const r = await fetch(`https://api.github.com${p}`, {
    ...init,
    headers: { Authorization: `Bearer ${T}`, Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28', ...(init.body ? { 'Content-Type': 'application/json' } : {}) }
  });
  if (!r.ok) throw new Error(`${p} -> ${r.status} ${(await r.text()).slice(0, 200)}`);
  return r.status === 204 ? null : r.json();
};
const b64 = s => Buffer.from(s, 'utf8').toString('base64');

// ---- what to seed -------------------------------------------------------------------
const now = new Date();
const Y = now.getFullYear(), M = now.getMonth();
const d = n => { const x = new Date(Y, M, n, 12); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
const z = (day, h, mi = 0) => new Date(Date.UTC(Y, M, day, h, mi)).toISOString().replace(/\.\d{3}Z$/, 'Z');

const GROUPS = `---
groups:
  work:    { color: "#c0392b", label: "Work" }
  home:    { color: "#27ae60", label: "Household" }
  health:  { color: "#2980b9", label: "Sport & Doctor" }
  family:  { color: "#8e44ad", label: "Family" }
  travel:  { color: "#d98300", label: "Travel" }
---

Maps an entry's \`group\` name to a colour and a label. Editing a colour here recolours every
entry in that group; no entry files are touched.
`;

// Fixed ids so re-running overwrites rather than duplicating.
const WEEKLY_ID = 'p7qm';
const files = [{ path: 'calendar/groups.md', text: GROUPS }];
const add = (id, data, body) => files.push(entryFile(data, body, pathFor(data, id)));

add('k3f9', { title: 'Project Phoenix: Weekly Sync', type: 'event', start: z(4, 14), end: z(4, 15),
  group: 'work', location: 'Virtual / Conference Room 3B', alerts: [0, 15],
  participants: ['jane.doe@example.com', 'john.smith@example.com'] },
  '# Agenda: Project Phoenix Sync\n\nWeekly alignment. Come with progress and blockers.\n');

// Umlauts, in the title and in the body, to prove the UTF-8 round trip.
add('u9x2', { title: 'Zahnärztin — Kontrolluntersuchung', type: 'event', start: z(9, 8, 30),
  end: z(9, 9, 15), group: 'health', location: 'Praxis Dr. Müller, Grünstraße 7', alerts: [60] },
  'Röntgenbilder mitbringen. Überweisung liegt im Flur.\n');

add('m4kd', { title: 'Großeltern besuchen', type: 'event', start: d(21), end: d(22),
  group: 'family', location: 'Würzburg' }, 'Zwei Tage. Kuchen mitnehmen.\n');

add('t1qz', { title: 'Flight BER → LIS', type: 'event', start: z(26, 6, 45), end: z(26, 9, 55),
  group: 'travel', location: 'BER Terminal 1', alerts: [0, 120] }, 'Seat 14A. Hand luggage only.\n');

add('w7cc', { title: 'Steuererklärung abschicken', type: 'task', start: d(13), done: false,
  group: 'home', alerts: [0] }, '- [ ] Belege scannen\n- [ ] Elster hochladen\n');

add('r2mb', { title: 'Lauftraining', type: 'task', start: z(6, 17, 30), done: true,
  group: 'health' }, '10 km, locker.\n');

add('q8hv', { title: 'Quartalsbericht fertigstellen', type: 'task', start: d(17), done: false,
  group: 'work' }, 'Zahlen von Finance abwarten.\n');

// The weekly recurring task: one occurrence skipped via exdate, one ticked via an override.
const satOf = week => { const x = new Date(Y, M, 1, 12); x.setDate(1 + ((6 - x.getDay() + 7) % 7) + 7 * week);
  return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
const first = satOf(0), ticked = satOf(1), skipped = satOf(2);

add(WEEKLY_ID, { title: 'Müll rausbringen', type: 'task', start: first, done: false, group: 'home',
  recurrence: 'FREQ=WEEKLY;BYDAY=SA', exdate: [skipped], alerts: [0] },
  '- Put trashcan next to street with handlebar facing towards the street\n- Clean it afterwards\n');

const seriesId = pathFor({ title: 'Müll rausbringen', recurrence: 'x' }, WEEKLY_ID)
  .split('/').pop().replace(/\.md$/, '');
add('ov1q', { series: seriesId, 'recurrence-id': ticked, done: true },
  'Ticked off for this one week. Only the keys that differ from the series are present.\n');

add('y5np', { title: 'Yoga', type: 'event', start: z(2, 18), end: z(2, 19, 15), group: 'health',
  recurrence: 'FREQ=WEEKLY;BYDAY=TU,TH;COUNT=8' }, 'Mat is in the car.\n');

// ---- commit it all as one tree --------------------------------------------------------
const ref = await api(`/repos/${O}/${R}/git/ref/heads/${B}`);
const parent = ref.object.sha;
const baseTree = (await api(`/repos/${O}/${R}/git/commits/${parent}`)).tree.sha;
const tree = [];
for (const f of files) {
  const blob = await api(`/repos/${O}/${R}/git/blobs`, { method: 'POST', body: JSON.stringify({ content: b64(f.text), encoding: 'base64' }) });
  tree.push({ path: f.path, mode: '100644', type: 'blob', sha: blob.sha });
}
const t = await api(`/repos/${O}/${R}/git/trees`, { method: 'POST', body: JSON.stringify({ base_tree: baseTree, tree }) });
const c = await api(`/repos/${O}/${R}/git/commits`, { method: 'POST', body: JSON.stringify({ message: 'Seed the calendar with development data', tree: t.sha, parents: [parent] }) });
await api(`/repos/${O}/${R}/git/refs/heads/${B}`, { method: 'PATCH', body: JSON.stringify({ sha: c.sha, force: false }) });
console.log('committed', c.sha.slice(0, 7), '-', files.length, 'files');
for (const f of files) console.log('  ', f.path);

// ---- read it back from GitHub and compare byte for byte --------------------------------
const full = await api(`/repos/${O}/${R}/git/trees/${B}?recursive=1`);
const back = [];
for (const e of full.tree.filter(x => x.type === 'blob' && x.path.startsWith('calendar/'))) {
  const blob = await api(`/repos/${O}/${R}/git/blobs/${e.sha}`);
  back.push({ path: e.path, text: Buffer.from(blob.content, 'base64').toString('utf8') });
}
let bad = 0;
for (const f of files) {
  const got = back.find(b => b.path === f.path);
  if (!got) { console.log('MISSING', f.path); bad++; }
  else if (got.text !== f.text) { console.log('DIFFERS', f.path); bad++; }
}
console.log(bad ? `\n${bad} file(s) did not round-trip` : `\nround trip exact for all ${files.length} files`);

console.log('\n=== parsed back through the read path (TZ=' + (process.env.TZ || 'system') + ') ===');
const m = buildModel(back);
console.log('groups:', Object.keys(m.groups).join(', '));
console.log('dated:', m.dated.length, '| rules:', m.rules.map(r => r.id).join(', '), '| overrides:', [...m.overrides.keys()].join(', '));
const from = d(1), to = `${Y}-${String(M + 1).padStart(2, '0')}-${new Date(Y, M + 1, 0).getDate()}`;
for (const o of occurrences(m, from, to))
  console.log(` ${o.dayKey} ${(timeLabel(o.start) || 'all-day').padEnd(7)} ${o.type.padEnd(5)} ${o.done ? '[x]' : o.type === 'task' ? '[ ]' : '   '} ${o.group.padEnd(6)} ${o.title}${o.override ? '  (override)' : ''}`);
console.log(`\nskipped occurrence ${skipped} must be absent; ticked occurrence ${ticked} must show [x]`);
